from __future__ import annotations

from pathlib import Path

import yaml

from secretscan.rules.rule import CompiledRule, Rule


def _parse_rule(data: dict) -> Rule:
    entropy = data.get("entropy", {})
    return Rule(
        id=data["id"],
        description=data.get("description", ""),
        regex=data["regex"],
        secret_group=data.get("secretGroup", 0),
        keywords=data.get("keywords", []),
        entropy_enabled=entropy.get("enabled", False),
        entropy_min=entropy.get("min", 0.0),
        severity=data.get("severity", "low"),
        tags=data.get("tags", []),
        hash_scope=data.get("hashScope", "value"),
    )


def load_rules_file(path: str | Path) -> list[CompiledRule]:
    with open(path) as f:
        doc = yaml.safe_load(f)
    return [CompiledRule(_parse_rule(r)) for r in doc.get("rules", [])]


def load_default_rules() -> list[CompiledRule]:
    default_path = Path(__file__).parent / "default.yaml"
    return load_rules_file(default_path)
